function openJournal(chunks) {
  const NO_EVENT = Symbol("no-event");

  const NEW = 0;
  const OPEN = 1;
  const EOF = 2;
  const CLOSED = 3;
  const FAILED = 4;

  let status = NEW;
  let iterator;
  let acquired = false;
  let sourceDone = false;
  let buffer = "";
  let lineNumber = 1;
  let returnStarted = false;
  let returnPromise = null;
  let closePromise = null;

  const decoder = new TextDecoder("utf-8");

  function doneResult() {
    return { done: true, value: undefined };
  }

  function acquireIterator() {
    if (acquired) return;

    acquired = true;

    try {
      const method = chunks[Symbol.asyncIterator];

      if (typeof method !== "function") {
        throw new TypeError("chunks must be an async iterable");
      }

      iterator = method.call(chunks);

      if (
        iterator === null ||
        (typeof iterator !== "object" &&
          typeof iterator !== "function") ||
        typeof iterator.next !== "function"
      ) {
        throw new TypeError("async iterator is invalid");
      }

      status = OPEN;
    } catch (error) {
      status = FAILED;
      throw error;
    }
  }

  function startReturn() {
    if (returnStarted) return returnPromise;

    returnStarted = true;

    if (iterator === undefined || iterator === null) {
      returnPromise = Promise.resolve();
      return returnPromise;
    }

    let method;

    try {
      method = iterator.return;
    } catch (error) {
      returnPromise = Promise.reject(error);
      return returnPromise;
    }

    if (typeof method !== "function") {
      returnPromise = Promise.resolve();
      return returnPromise;
    }

    try {
      returnPromise = Promise.resolve(method.call(iterator));
    } catch (error) {
      returnPromise = Promise.reject(error);
    }

    return returnPromise;
  }

  async function failRead(error) {
    status = FAILED;

    if (!sourceDone) {
      try {
        await startReturn();
      } catch (_) {
        // Preserve the original read error.
      }
    }
  }

  function parseLine(text) {
    const line = lineNumber++;

    if (text.trim().length === 0) {
      return NO_EVENT;
    }

    try {
      return {
        line,
        ok: true,
        value: JSON.parse(text)
      };
    } catch (_) {
      return {
        line,
        ok: false,
        text
      };
    }
  }

  function takeEvent() {
    for (;;) {
      const newline = buffer.indexOf("\n");

      if (newline !== -1) {
        let end = newline;

        if (end > 0 && buffer.charCodeAt(end - 1) === 13) {
          end -= 1;
        }

        const text = buffer.slice(0, end);
        buffer = buffer.slice(newline + 1);

        const event = parseLine(text);

        if (event !== NO_EVENT) {
          return event;
        }

        continue;
      }

      if (!sourceDone || buffer.length === 0) {
        return NO_EVENT;
      }

      const text = buffer;
      buffer = "";

      const event = parseLine(text);

      if (event !== NO_EVENT) {
        return event;
      }
    }
  }

  async function next() {
    if (status === CLOSED || status === EOF || status === FAILED) {
      return doneResult();
    }

    acquireIterator();

    for (;;) {
      const event = takeEvent();

      if (event !== NO_EVENT) {
        return { done: false, value: event };
      }

      if (sourceDone) {
        status = EOF;
        return doneResult();
      }

      let result;

      try {
        result = await iterator.next();
      } catch (error) {
        await failRead(error);
        throw error;
      }

      if (status === CLOSED) {
        return doneResult();
      }

      let isDone;

      try {
        if (
          result === null ||
          (typeof result !== "object" && typeof result !== "function")
        ) {
          throw new TypeError("async iterator result is invalid");
        }

        isDone = Boolean(result.done);
      } catch (error) {
        await failRead(error);
        throw error;
      }

      if (isDone) {
        sourceDone = true;

        let tail;

        try {
          tail = decoder.decode();
        } catch (error) {
          await failRead(error);
          throw error;
        }

        buffer += tail;
        continue;
      }

      let decoded;

      try {
        decoded = decoder.decode(result.value, { stream: true });
      } catch (error) {
        await failRead(error);
        throw error;
      }

      buffer += decoded;
    }
  }

  function close() {
    if (closePromise !== null) {
      return closePromise;
    }

    closePromise = (async function () {
      if (status === NEW) {
        status = CLOSED;
        return;
      }

      if (status === OPEN) {
        status = CLOSED;

        if (!sourceDone) {
          await startReturn();
        }

        return;
      }

      if (status === FAILED && returnPromise !== null) {
        await returnPromise;
      }
    })();

    return closePromise;
  }

  return { next, close };
}
